mod audio;mod game;mod video;
use game::Game;
fn main(){let mut out=vec![];for name in ["bullet","grenade","rocket","wave_horizontal","wave_vertical"] {for facing in 1..=8{if (name=="bullet" || name.starts_with("wave"))&&facing>1{continue}let mut g=Game::new(false).unwrap();g.memory.fill(0);let slot=if name=="bullet"{18}else{24};g.memory[0x39]=slot;g.memory[0x520+slot as usize]=match name{"bullet"|"grenade"=>1,"rocket"=>5,_=>9};g.memory[0x5a0+slot as usize]=128;g.memory[0x560+slot as usize]=128;g.memory[0x62]=facing;g.memory[0x50]=3;g.memory[0x764]=u8::from(name=="wave_vertical");let mut samples=vec![];for tick in 0..90{g.memory[0x1a]=tick;g.actor_call(if name=="bullet"{0xed2c}else{0xeda4},0).unwrap();samples.push(serde_json::json!({"tick":tick,"sprite":g.memory[0x500+slot as usize],"flips":g.memory[if name=="bullet"{0x7c}else{0x82}],"x":g.memory[0x5a0+slot as usize] as f32+g.memory[0x5c0+slot as usize] as f32/256.,"y":g.memory[0x560+slot as usize] as f32+g.memory[0x580+slot as usize] as f32/256.,"state":g.memory[0x520+slot as usize],"timer":g.memory[if name=="bullet"{0x750}else{0x75c}],"horizontal_wave":g.memory[0x53a],"vertical_wave":g.memory[0x53c]}));if g.memory[0x520+slot as usize]==0{break}}out.push(serde_json::json!({"weapon":name,"facing":facing,"samples":samples}));}}println!("{}",serde_json::to_string_pretty(&out).unwrap());}
